package com.neu.riketiku.xueshenglianxi;import static org.assertj.core.api.Assertions.*;import org.junit.jupiter.api.Test;import tools.jackson.databind.ObjectMapper;
class ObjectiveAnswerGraderTest{final ObjectiveAnswerGrader grader=new ObjectiveAnswerGrader();final ObjectMapper mapper=new ObjectMapper();@Test void gradesAllSupportedStructuresDeterministically(){String options="[{\"label\":\"A\",\"content\":\"a\"},{\"label\":\"B\",\"content\":\"b\"}]";assertThat(grader.grade("SINGLE_CHOICE","{\"optionLabels\":[\"A\"]}",options,mapper.readTree("\"A\""))).isTrue();assertThat(grader.grade("MULTIPLE_CHOICE","{\"optionLabels\":[\"A\",\"B\"]}",options,mapper.readTree("[\"B\",\"A\"]"))).isTrue();assertThat(grader.grade("FILL_BLANK","{\"blanks\":[{\"index\":1,\"acceptedAnswers\":[\"H2O\"]}]}","[]",mapper.readTree("[\"h2o\"]"))).isTrue();}}
